async def blocked_pair(p):
 return await p.evaluate('''async()=>{const g=(await import('./game.mjs')).diagnostics(),{LEVELS}=await import('./levels.mjs'),{findPath}=await import('./engine.mjs');for(let a=0;a<g.board.length;a++)for(let b=a+1;b<g.board.length;b++)if(g.board[a]&&g.board[b]&&g.board[a].kind===g.board[b].kind&&!findPath(LEVELS[g.level-1],g.board,a,b))return {a,b};return null;}''')
async def certificate(p):return await p.evaluate('async()=>{const g=(await import("./game.mjs")).diagnostics();return (await import("./engine.mjs")).solveBoard((await import("./levels.mjs")).LEVELS[g.level-1],g.board,20000)}')
def tiles(s):return sorted((t['id'],t['kind']) for t in s['board'] if t)
